(4982465, 726081, 62187, '<td valign="top">Pretty clever on the dead vine...emotional but not very abstract to me.</td>', 'Pretty clever on the dead vine...emotional but not very abstract to me.', '2008-09-30 22:20:42.000000', NULL, 1),
