(4982545, 725295, 62187, '<td valign="top">Ummmm....abstract? I want it to be. Emotional? Abstractly. It''s wicked cool for sure. 7</td>', 'Ummmm....abstract? I want it to be. Emotional? Abstractly. It''s wicked cool for sure. 7', '2008-09-30 23:07:59.000000', NULL, 1),
(4982547, 725849, 62187, '<td valign="top">I like it...extremely! 10</td>', 'I like it...extremely! 10', '2008-09-30 23:08:48.000000', NULL, 1),
(4982586, 726080, 62187, '<td valign="top">I must say, it looks very abstract and there is some emotion. I think if it were in black and white, it might have looked quit scary: like the grim reaper.</td>', 'I must say, it looks very abstract and there is some emotion. I think if it were in black and white, it might have looked quit scary: like the grim reaper.', '2008-09-30 23:48:12.000000', NULL, 1),
(4982587, 726065, 62187, '<td valign="top">I don''t know about ''rage'' but ok.  It''s abstract that''s for sure.</td>', 'I don''t know about ''rage'' but ok.  It''s abstract that''s for sure.', '2008-09-30 23:49:00.000000', NULL, 1),
(4982588, 726012, 62187, '<td valign="top">It''s a 10 to me. Certainly abstract and yes, I do get the feeling it is late in the day: as in - long light.</td>', 'It''s a 10 to me. Certainly abstract and yes, I do get the feeling it is late in the day: as in - long light.', '2008-09-30 23:49:54.000000', NULL, 1),
