(4986745, 725544, 54478, '<td valign="top">I like this photo. It feels a little dark and I think it would be most excellent in black and white, but the blue hue works well here as well.</td>', 'I like this photo. It feels a little dark and I think it would be most excellent in black and white, but the blue hue works well here as well.', '2008-10-02 10:37:07.000000', NULL, 1),
(4986754, 725576, 54478, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2008-10-02 10:44:28.000000', NULL, 1),
