(4986770, 725312, 54478, '<td valign="top">I love the concept, I wish the DOF was long enough to include the eyes of the snake.</td>', 'I love the concept, I wish the DOF was long enough to include the eyes of the snake.', '2008-10-02 10:49:31.000000', NULL, 1),
(4986771, 725295, 54478, '<td valign="top">I love the texture. I wish the eye was a little lower and to the right to more adequately use the rule of thirds.</td>', 'I love the texture. I wish the eye was a little lower and to the right to more adequately use the rule of thirds.', '2008-10-02 10:50:25.000000', NULL, 1),
