(4988853, 725219, 10985, '<td valign="top">Artistic!</td>', 'Artistic!', '2008-10-03 01:29:04.000000', NULL, 1),
(4988859, 725880, 10985, '<td valign="top">Very nice. I suggest Loneliness, as this is what a lonely person feeding the birds must see, sometimes.</td>', 'Very nice. I suggest Loneliness, as this is what a lonely person feeding the birds must see, sometimes.', '2008-10-03 01:31:55.000000', NULL, 1),
(4988860, 725978, 10985, '<td valign="top">Great colors and movement!</td>', 'Great colors and movement!', '2008-10-03 01:32:33.000000', NULL, 1),
(4988867, 725551, 10985, '<td valign="top">This works very well. It was a very hard challenge and you really captured it!</td>', 'This works very well. It was a very hard challenge and you really captured it!', '2008-10-03 01:37:06.000000', NULL, 1),
(4988870, 726086, 10985, '<td valign="top">Beautiful photo. The title doesn''t do it justice...</td>', 'Beautiful photo. The title doesn''t do it justice...', '2008-10-03 01:38:12.000000', NULL, 1),
(4988878, 725295, 10985, '<td valign="top">Very impressive close-up. Great detail and post-processing.</td>', 'Very impressive close-up. Great detail and post-processing.', '2008-10-03 01:42:40.000000', NULL, 1),
(4988885, 725728, 10985, '<td valign="top">Hey, I just saw her in the portrait challenge... :) The lighting is still flat, and the composition and expression are still quite lively!</td>', 'Hey, I just saw her in the portrait challenge... :) The lighting is still flat, and the composition and expression are still quite lively!', '2008-10-03 01:45:43.000000', NULL, 1),
(4988888, 725753, 10985, '<td valign="top">Great shot, but all that power doesn''t say serenity to me. It does say power, self-assurance, strength, but not serenity. (Which doesn''t bring my vote down: the emotion is here and the photo is excellent.)</td>', 'Great shot, but all that power doesn''t say serenity to me. It does say power, self-assurance, strength, but not serenity. (Which doesn''t bring my vote down: the emotion is here and the photo is excellent.)', '2008-10-03 01:47:34.000000', NULL, 1),
(4988892, 725312, 10985, '<td valign="top">Soooo effective!</td>', 'Soooo effective!', '2008-10-03 01:51:49.000000', NULL, 1),
(4988893, 726074, 10985, '<td valign="top">Great great shot!</td>', 'Great great shot!', '2008-10-03 01:51:51.000000', NULL, 1),
(4988922, 725868, 60224, '<td valign="top">Soft</td>', 'Soft', '2008-10-03 02:31:45.000000', NULL, 1),
(4988946, 726074, 60224, '<td valign="top">WOW</td>', 'WOW', '2008-10-03 02:44:55.000000', NULL, 1),
(4989035, 726036, 30982, '<td valign="top">Love how the bokeh forms a second "web" of sorts.</td>', 'Love how the bokeh forms a second "web" of sorts.', '2008-10-03 04:31:07.000000', NULL, 1),
(4989036, 726012, 30982, '<td valign="top">Beautiful abstract!!  Well titled - I can hear the song in my head now.</td>', 'Beautiful abstract!!  Well titled - I can hear the song in my head now.', '2008-10-03 04:32:34.000000', NULL, 1),
(4989037, 726016, 30982, '<td valign="top">A lively sense of vibrance and indeed a seize the day kinda thing.  Well done for the challenge and fun photograph on its own.</td>', 'A lively sense of vibrance and indeed a seize the day kinda thing.  Well done for the challenge and fun photograph on its own.', '2008-10-03 04:33:11.000000', NULL, 1),
(4989038, 726050, 30982, '<td valign="top">Probably not abstract to voters but a lovely fall photograph and I can see your correlation based on the title.</td>', 'Probably not abstract to voters but a lovely fall photograph and I can see your correlation based on the title.', '2008-10-03 04:34:33.000000', NULL, 1),
(4989039, 726065, 30982, '<td valign="top">Interesting - where you see rage, I see longing and admiration.  I see a figure of a man in the smoek on the right, a ballerina facing away from him on the left, with a flowing dress billowing behind her.</td>', 'Interesting - where you see rage, I see longing and admiration.  I see a figure of a man in the smoek on the right, a ballerina facing away from him on the left, with a flowing dress billowing behind her.', '2008-10-03 04:35:41.000000', NULL, 1),
(4989041, 726080, 30982, '<td valign="top">Nailed it!  Wonderful rich color, warmth.  Really very pleasing indeed.</td>', 'Nailed it!  Wonderful rich color, warmth.  Really very pleasing indeed.', '2008-10-03 04:36:26.000000', NULL, 1),
(4989042, 725998, 30982, '<td valign="top">You see love, I see something that''s overwhelming, engulfing.  I suppose that could be love, huh?</td>', 'You see love, I see something that''s overwhelming, engulfing.  I suppose that could be love, huh?', '2008-10-03 04:37:41.000000', NULL, 1),
(4989045, 725849, 30982, '<td valign="top">Beautiful photograph - I love the graininess, the memory of it.  Well suited to the challenge.</td>', 'Beautiful photograph - I love the graininess, the memory of it.  Well suited to the challenge.', '2008-10-03 04:40:52.000000', NULL, 1),
(4989048, 724875, 30982, '<td valign="top">Speaks to me of death and decay - very intersting find!</td>', 'Speaks to me of death and decay - very intersting find!', '2008-10-03 04:44:03.000000', NULL, 1),
(4989049, 725765, 30982, '<td valign="top">Very nicely done!</td>', 'Very nicely done!', '2008-10-03 04:44:56.000000', NULL, 1),
(4989050, 726007, 30982, '<td valign="top">An odd choice, but also oddly effective.  A sense of longing, of loss in a way.  A reaching to that which cannot be.  I think I''d have preferred it without the reflection, though.</td>', 'An odd choice, but also oddly effective.  A sense of longing, of loss in a way.  A reaching to that which cannot be.  I think I''d have preferred it without the reflection, though.', '2008-10-03 04:46:01.000000', NULL, 1),
(4989055, 726013, 30982, '<td valign="top">Ooooh - lovely!  My kind of shot.  Well titled also.</td>', 'Ooooh - lovely!  My kind of shot.  Well titled also.', '2008-10-03 04:56:32.000000', NULL, 1),
(4989056, 724654, 30982, '<td valign="top">Cool shot!  And this is one of those times when the blue fringing works for the shot.  Great perspective, interesting take on the challenge.</td>', 'Cool shot!  And this is one of those times when the blue fringing works for the shot.  Great perspective, interesting take on the challenge.', '2008-10-03 04:57:38.000000', NULL, 1),
(4989057, 725776, 36596, '<td valign="top">Excellent.</td>', 'Excellent.', '2008-10-03 05:04:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4989060, 725295, 30982, '<td valign="top">From the thumb, it''s clearly discernible what the subject is, but when you open it, it takes on a whole different look and story.  Almost depressing in a way - a tale of a world in disarray.</td>', 'From the thumb, it''s clearly discernible what the subject is, but when you open it, it takes on a whole different look and story.  Almost depressing in a way - a tale of a world in disarray.', '2008-10-03 05:13:51.000000', NULL, 1),
(4989062, 725618, 30982, '<td valign="top">Not sure it would be considered an abstract, but it''s a darn cool shot!</td>', 'Not sure it would be considered an abstract, but it''s a darn cool shot!', '2008-10-03 05:14:18.000000', NULL, 1),
(4989065, 725064, 30982, '<td valign="top">Beautiful abstract!!  Title suits it nicely as well.</td>', 'Beautiful abstract!!  Title suits it nicely as well.', '2008-10-03 05:15:07.000000', NULL, 1),
(4989067, 725719, 30982, '<td valign="top">This works very well for me - the view of the eye has a harshness, almost an anger to it, and the blur of the bokeh depicts a wildness that the beast longs for.</td>', 'This works very well for me - the view of the eye has a harshness, almost an anger to it, and the blur of the bokeh depicts a wildness that the beast longs for.', '2008-10-03 05:16:34.000000', NULL, 1),
(4989068, 725310, 30982, '<td valign="top">Yep, works for me.</td>', 'Yep, works for me.', '2008-10-03 05:16:56.000000', NULL, 1),
(4989070, 725294, 30982, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2008-10-03 05:18:16.000000', NULL, 1),
(4989073, 726037, 30982, '<td valign="top">Definitely conveys a sense of isolationism.</td>', 'Definitely conveys a sense of isolationism.', '2008-10-03 05:19:40.000000', NULL, 1),
(4989698, 725896, 30982, '<td valign="top">Ominous.  And rather fascinating.</td>', 'Ominous.  And rather fascinating.', '2008-10-03 13:51:22.000000', NULL, 1),
(4989700, 725219, 30982, '<td valign="top">Wonderful blur!!  The tones and lines created in this are excellent.</td>', 'Wonderful blur!!  The tones and lines created in this are excellent.', '2008-10-03 13:52:07.000000', NULL, 1),
(4989706, 725415, 30982, '<td valign="top">Or heartbreak.</td>', 'Or heartbreak.', '2008-10-03 13:54:21.000000', NULL, 1),
(4989709, 726005, 30982, '<td valign="top">Very cool result!</td>', 'Very cool result!', '2008-10-03 13:56:40.000000', NULL, 1),
(4989711, 726030, 30982, '<td valign="top">Love the high key.</td>', 'Love the high key.', '2008-10-03 13:57:01.000000', NULL, 1),
(4989747, 725952, 30982, '<td valign="top">I really like the feel of this.  It''s rather empty, lonely.  One of those places that looks inviting, but no one ever sits there.  Intriguing, and very well photographed.</td>', 'I really like the feel of this.  It''s rather empty, lonely.  One of those places that looks inviting, but no one ever sits there.  Intriguing, and very well photographed.', '2008-10-03 14:12:55.000000', NULL, 1),
(4989769, 726074, 30791, '<td valign="top">i just cant fathom the editing steps you take to achieve this look yanko.</td>', 'i just cant fathom the editing steps you take to achieve this look yanko.', '2008-10-03 14:23:02.000000', NULL, 1),
(4989775, 724884, 30791, '<td valign="top">best idea for the challenge, hands down<br/>10</td>', 'best idea for the challenge, hands down10', '2008-10-03 14:24:54.000000', NULL, 1),
(4989781, 726037, 30791, '<td valign="top">my top pick for this challenge, remarkable photo, suits the challenge very well</td>', 'my top pick for this challenge, remarkable photo, suits the challenge very well', '2008-10-03 14:26:22.000000', NULL, 1),
(4989784, 725952, 83313, '<td valign="top">A rare case of an out of focus image being the perfect way to convey of a concept. This suggests to me that someone is bleary-eyed from crying. I''m really curious to see where this one winds up in the rankings. As for me, I''m giving it a 9. Good job on this.</td>', 'A rare case of an out of focus image being the perfect way to convey of a concept. This suggests to me that someone is bleary-eyed from crying. I''m really curious to see where this one winds up in the rankings. As for me, I''m giving it a 9. Good job on this.', '2008-10-03 14:28:09.000000', NULL, 1),
(4989791, 725276, 30791, '<td valign="top">a great combination of shallow DOF and composition and lighting</td>', 'a great combination of shallow DOF and composition and lighting', '2008-10-03 14:28:57.000000', NULL, 1),
(4989792, 725986, 83313, '<td valign="top">Trying to figure out what the emotion is here. Very bold and ought to do well.</td>', 'Trying to figure out what the emotion is here. Very bold and ought to do well.', '2008-10-03 14:29:07.000000', NULL, 1),
(4989799, 726016, 83313, '<td valign="top">..or you could spell it as "Carp Diem" (Seize the fish)</td>', '..or you could spell it as "Carp Diem" (Seize the fish)', '2008-10-03 14:30:50.000000', NULL, 1),
(4989805, 725985, 83313, '<td valign="top">Probably just a flower, but it does suggest something more sexual in nature.</td>', 'Probably just a flower, but it does suggest something more sexual in nature.', '2008-10-03 14:31:46.000000', NULL, 1),
