(4989854, 725242, 83313, '<td valign="top">Sorry, I''m not finding this terribly creative or appealing to me. I''ve occasionally done one like this myself, and reflected clouds seems to be something that looks really neat in person, but is hard to effectively capture.</td>', 'Sorry, I''m not finding this terribly creative or appealing to me. I''ve occasionally done one like this myself, and reflected clouds seems to be something that looks really neat in person, but is hard to effectively capture.', '2008-10-03 14:48:13.000000', NULL, 1),
(4989856, 725400, 83313, '<td valign="top">One of those titles that has me scrambling for the dictionary.</td>', 'One of those titles that has me scrambling for the dictionary.', '2008-10-03 14:49:03.000000', NULL, 1),
