(4990536, 725782, 50695, '<td valign="top">I really do get a sense of narcissism from this, even before I discerned your reflection. Well done.</td>', 'I really do get a sense of narcissism from this, even before I discerned your reflection. Well done.', '2008-10-03 21:00:16.000000', NULL, 1),
(4990537, 726073, 50695, '<td valign="top">This conveys emotion through facial expression, but the repetition both enhances the emotion and makes it more abstract, so I''ll give you a 7.</td>', 'This conveys emotion through facial expression, but the repetition both enhances the emotion and makes it more abstract, so I''ll give you a 7.', '2008-10-03 21:01:00.000000', NULL, 1),
