INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4994038, 725745, 61651, '<td valign="top">Cool beans! This was an 8 from me, liked it very much, even though at the time I did not see faces.  Now I do, and wow! :)</td>', 'Cool beans! This was an 8 from me, liked it very much, even though at the time I did not see faces.  Now I do, and wow! :)', '2008-10-06 01:05:13.000000', NULL, 0),
(4994044, 726080, 61651, '<td valign="top">Very artful and a prime example of how art is everywhere, if we would only see it.  I too, thought you were <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=74588" rel="nofollow" target="_blank">cutout</a>. :)</td>', 'Very artful and a prime example of how art is everywhere, if we would only see it.  I too, thought you were  cutout. :)', '2008-10-06 01:06:58.000000', NULL, 0),
(4994047, 726080, 66384, '<td valign="top">Congratulations on the top ten little star. This is a wonderful abstract. I''m so glad a lot of people appreciated it.</td>', 'Congratulations on the top ten little star. This is a wonderful abstract. I''m so glad a lot of people appreciated it.', '2008-10-06 01:09:06.000000', NULL, 0),
(4994049, 725880, 61651, '<td valign="top">I wonder how many people saw this and thought of your Ode to Joy - I know I did.  Never would have guessed this would be you again! :)  I love all the complementary green here - such variety, but it all comes together.</td>', 'I wonder how many people saw this and thought of your Ode to Joy - I know I did.  Never would have guessed this would be you again! :)  I love all the complementary green here - such variety, but it all comes together.', '2008-10-06 01:09:47.000000', NULL, 0),
(4994051, 725551, 61651, '<td valign="top">One of my 10s - excellent evocation of this emotion.</td>', 'One of my 10s - excellent evocation of this emotion.', '2008-10-06 01:10:22.000000', NULL, 0),
(4994053, 725219, 27133, '<td valign="top">Congrats girl on top 15.</td>', 'Congrats girl on top 15.', '2008-10-06 01:11:38.000000', NULL, 0),
(4994058, 725745, 66384, '<td valign="top">Congratulations on the well deserved 5th place.</td>', 'Congratulations on the well deserved 5th place.', '2008-10-06 01:12:47.000000', NULL, 0),
(4994061, 726074, 61818, '<td valign="top">Water drops fallen from eyes irritated by a chemical reaction is an abstract of an emotion?  Even reading your notes I can''t make the connection.  Fine looking shot to be sure.  I''ll have to puzzle out the rest on my own.</td>', 'Water drops fallen from eyes irritated by a chemical reaction is an abstract of an emotion?  Even reading your notes I can''t make the connection.  Fine looking shot to be sure.  I''ll have to puzzle out the rest on my own.', '2008-10-06 01:13:10.000000', NULL, 0),
(4994078, 725531, 61651, '<td valign="top">You''re 2nd place on the zone plate page. :)  This one has such a shining sense of hope to it, for me.</td>', 'You''re 2nd place on the zone plate page. :)  This one has such a shining sense of hope to it, for me.', '2008-10-06 01:16:11.000000', NULL, 0),
(4994088, 725400, 50641, '<td valign="top">haha, it''s you!  i think you already know that sartre joke!  great pic!</td>', 'haha, it''s you!  i think you already know that sartre joke!  great pic!', '2008-10-06 01:18:29.000000', NULL, 0),
(4994090, 725880, 66384, '<td valign="top">Well, look at that. I wondered who was copying your Ode to Joy, and lo and behold, it was yourself. :D Beautiful. Now you have a great pair.</td>', 'Well, look at that. I wondered who was copying your Ode to Joy, and lo and behold, it was yourself. :D Beautiful. Now you have a great pair.', '2008-10-06 01:19:20.000000', NULL, 0),
(4994105, 725745, 53814, '<td valign="top">beautiful!</td>', 'beautiful!', '2008-10-06 01:23:46.000000', NULL, 0),
(4994111, 724875, 61961, '<td valign="top">Awesome.  I''d recognize this as yours after your recent series of portfolio abstracts.  Congrats on your top ten.</td>', 'Awesome.  I''d recognize this as yours after your recent series of portfolio abstracts.  Congrats on your top ten.', '2008-10-06 01:26:31.000000', NULL, 0),
(4994112, 726037, 66515, '<td valign="top">Congrats on your first blue! I am glad I was wrong about the bubbles! :)</td>', 'Congrats on your first blue! I am glad I was wrong about the bubbles! :)', '2008-10-06 01:26:37.000000', NULL, 0),
(4994115, 726037, 52549, '<td valign="top">Excellent idea, well carried out. Congrats on your blue ribbon, Marco.</td>', 'Excellent idea, well carried out. Congrats on your blue ribbon, Marco.', '2008-10-06 01:27:17.000000', NULL, 0),
(4994117, 725842, 62187, '<td valign="top">...just like I thought...</td>', '...just like I thought...', '2008-10-06 01:29:26.000000', NULL, 0),
(4994118, 725765, 52549, '<td valign="top">GREAT shot, great color, agree about the movie poster. Fantastic image and congrats on the Red, Rudi!</td>', 'GREAT shot, great color, agree about the movie poster. Fantastic image and congrats on the Red, Rudi!', '2008-10-06 01:29:32.000000', NULL, 0),
(4994122, 725415, 75713, '<td valign="top">I didn''t get a chance to come back and comment on this shot although I meant to as I liked it so much... I voted it an 8 - and am very surprised it scored in the range it did...rapture, love''s gift, is presented here perfectly - glowing, fragile, beautiful - you photgraphed this so well and met the challenge perfectly.</td>', 'I didn''t get a chance to come back and comment on this shot although I meant to as I liked it so much... I voted it an 8 - and am very surprised it scored in the range it did...rapture, love''s gift, is presented here perfectly - glowing, fragile, beautiful - you photgraphed this so well and met the challenge perfectly.', '2008-10-06 01:31:06.000000', NULL, 0),
(4994127, 726074, 52549, '<td valign="top">Love the textures, love the tones, love the whole thing. Big congrats on your ribbon, Richard.</td>', 'Love the textures, love the tones, love the whole thing. Big congrats on your ribbon, Richard.', '2008-10-06 01:33:12.000000', NULL, 0),
(4994132, 726074, 62187, '<td valign="top">Now that the show is over and I can read what everybody else had to comment, I''m glad to know I was not the only one. Like I said, it''s an awesome photo. Maybe the DPC stands for ''contest'' after all? Congrats - I guess...</td>', 'Now that the show is over and I can read what everybody else had to comment, I''m glad to know I was not the only one. Like I said, it''s an awesome photo. Maybe the DPC stands for ''contest'' after all? Congrats - I guess...', '2008-10-06 01:34:56.000000', NULL, 0),
(4994169, 725765, 97166, '<td valign="top">I had a face abstract too, but it wasn''t abstract enough to some people. lol.<br/> <br/>Congrats, this was my only 10.</td>', 'I had a face abstract too, but it wasn''t abstract enough to some people. lol. Congrats, this was my only 10.', '2008-10-06 01:45:08.000000', NULL, 0),
(4994173, 725880, 28742, '<td valign="top">Hey - we had the same emotion in mind. :) Well done, Deb!</td>', 'Hey - we had the same emotion in mind. :) Well done, Deb!', '2008-10-06 01:47:08.000000', NULL, 0),
(4994175, 725849, 68504, '<td valign="top">I found this most moving, immediately, and without thinking.  Your title (which could as well have been ''once'' without the periods) speaks simply but extremely well without naming.</td>', 'I found this most moving, immediately, and without thinking.  Your title (which could as well have been ''once'' without the periods) speaks simply but extremely well without naming.', '2008-10-06 01:48:05.000000', NULL, 0),
(4994180, 725765, 16230, '<td valign="top">Wicked good!</td>', 'Wicked good!', '2008-10-06 01:52:17.000000', NULL, 0),
(4994186, 725985, 66192, '<td valign="top">Shame this one didn''t fair that well. Great representation of abstract.</td>', 'Shame this one didn''t fair that well. Great representation of abstract.', '2008-10-06 01:55:13.000000', NULL, 0),
(4994192, 725576, 5112, '<td valign="top">EMP!  Yes. Love this place!  Good take on it.</td>', 'EMP!  Yes. Love this place!  Good take on it.', '2008-10-06 01:58:42.000000', NULL, 0),
(4994193, 726074, 27133, '<td valign="top">I knew this was yours.  Congrats.  I think..lol!</td>', 'I knew this was yours.  Congrats.  I think..lol!', '2008-10-06 01:58:47.000000', NULL, 0),
(4994204, 725400, 68504, '<td valign="top">This was the one that really stuck in my mind after an admittedly brief perusal of the entries.  It wasn''t the Sartre (though I loved skewsme''s link), it was the relentless topiary!  You found the right angle and colour treatment to bring it on home.</td>', 'This was the one that really stuck in my mind after an admittedly brief perusal of the entries.  It wasn''t the Sartre (though I loved skewsme''s link), it was the relentless topiary!  You found the right angle and colour treatment to bring it on home.', '2008-10-06 02:02:48.000000', NULL, 0),
(4994212, 724015, 90495, '<td valign="top">Grats on your top 20 John. I have to admit i didn''t get it but after reading your comment it makes sense. Very well thought out. Great image.</td>', 'Grats on your top 20 John. I have to admit i didn''t get it but after reading your comment it makes sense. Very well thought out. Great image.', '2008-10-06 02:05:37.000000', NULL, 0),
(4994225, 726074, 65319, '<td valign="top">Ahhh, Richard...I just LOVE this photo...you know why?!  Instantly, I was captured but then had to think about why...the water on the knife and the reflection within carries the abstract emotional impact as the heart of this photo for me.  As always, exceptional doesn''t begin to describe the beauty of your work and this photo does not disappoint your fans!!!  The emotional within the mundane! (I was a little disappointed not see any UFO''s though...;-P...)  Many congrats on your ribbon!</td>', 'Ahhh, Richard...I just LOVE this photo...you know why?!  Instantly, I was captured but then had to think about why...the water on the knife and the reflection within carries the abstract emotional impact as the heart of this photo for me.  As always, exceptional doesn''t begin to describe the beauty of your work and this photo does not disappoint your fans!!!  The emotional within the mundane! (I was a little disappointed not see any UFO''s though...;-P...)  Many congrats on your ribbon!', '2008-10-06 02:15:49.000000', NULL, 0),
(4994234, 725896, 18450, '<td valign="top">This one really unsettled me. Good work!!</td>', 'This one really unsettled me. Good work!!', '2008-10-06 02:22:39.000000', NULL, 0),
(4994241, 726037, 60862, '<td valign="top">Terrific concept and you shot it very well.  Congrats!</td>', 'Terrific concept and you shot it very well.  Congrats!', '2008-10-06 02:28:09.000000', NULL, 0),
(4994243, 726074, 48560, '<td valign="top">really interesting! congrats Richard</td>', 'really interesting! congrats Richard', '2008-10-06 02:28:45.000000', NULL, 0),
(4994245, 725745, 60862, '<td valign="top">Congrats on top 5!</td>', 'Congrats on top 5!', '2008-10-06 02:29:07.000000', NULL, 0),
(4994263, 726080, 50641, '<td valign="top">glad to see this is you - very evocative - an 8 from me.  congrats on top 10.</td>', 'glad to see this is you - very evocative - an 8 from me.  congrats on top 10.', '2008-10-06 02:39:43.000000', NULL, 0),
(4994266, 725576, 28742, '<td valign="top">I KNEW you''d come away with something good! Congrats on top ten!</td>', 'I KNEW you''d come away with something good! Congrats on top ten!', '2008-10-06 02:44:53.000000', NULL, 0),
(4994270, 725896, 28742, '<td valign="top">Lensbaby, baby! I thought this was excellent! Let''s look behind the scenes...<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=726151" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/25000-29999/28742/120/726151.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/25000-29999/28742/120/726151.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/25000-29999/28742/120/726151.jpg"/></a> <br/> <br/>:)</td>', 'Lensbaby, baby! I thought this was excellent! Let''s look behind the scenes...  :)', '2008-10-06 02:48:26.000000', NULL, 0),
